from music21 import *

# Helper function for adding notes to a measure
def add_notes_to_measure(measure, notes_and_durations):
    for note_name, duration_val in notes_and_durations:
        if isinstance(note_name, list):
            n = chord.Chord(note_name)
        else:
            n = note.Note(note_name)
        n.duration.quarterLength = duration_val
        measure.append(n)

# 1. Setup
score = stream.Score()
score.insert(0, metadata.Metadata())
score.metadata.title = 'Emergence'
score.metadata.composer = 'AI Composer'

piano_part = stream.Part()
piano_part.partName = 'Piano'
piano_part.id = 'piano'
piano_part.append(instrument.Piano())
piano_part.append(tempo.MetronomeMark(number=90))
piano_part.append(key.Key('c', 'minor'))

cello_part = stream.Part()
cello_part.partName = 'Cello'
cello_part.id = 'cello'
cello_part.append(instrument.Cello()) # Correct instantiation
cello_part.append(tempo.MetronomeMark(number=90))
cello_part.append(key.Key('c', 'minor'))

# 2. Composition
# Measures 1-8: Introduction - Piano ostinato
for i in range(8):
    m_piano = stream.Measure(number=i+1)
    m_cello = stream.Measure(number=i+1)
    if i < 4:
        m_piano.append(note.Rest(quarterLength=4.0))
    else:
        # Simple repeating pattern in C minor
        rh = chord.Chord(['G4', 'Bb4', 'Eb5'], quarterLength=4.0)
        lh_notes = [('C2', 1), ('G2', 1), ('C3', 1), ('G2', 1)]
        lh_stream = stream.Stream()
        for n, d in lh_notes:
            lh_stream.append(note.Note(n, quarterLength=d))
        m_piano.insert(0, rh)
        m_piano.insert(0, lh_stream)

    m_cello.append(note.Rest(quarterLength=4.0))
    piano_part.append(m_piano)
    cello_part.append(m_cello)

# Measures 9-16: Exposition - Cello enters
for i in range(8):
    m_piano = stream.Measure(number=9+i)
    m_cello = stream.Measure(number=9+i)

    # Piano continues ostinato with variation
    base_note = 'C2' if i % 2 == 0 else 'Ab1'
    lh_notes = [(base_note, 1), (note.Note(base_note).transpose('P8').nameWithOctave, 1), (note.Note(base_note).transpose('P12').nameWithOctave, 1), (note.Note(base_note).transpose('P8').nameWithOctave, 1)]
    lh_stream = stream.Stream()
    for n, d in lh_notes:
        lh_stream.append(note.Note(n, quarterLength=d))

    rh_chord = chord.Chord(['Eb4', 'G4', 'Bb4'], quarterLength=4.0) if i % 2 == 0 else chord.Chord(['F4', 'Ab4', 'C5'], quarterLength=4.0)
    m_piano.insert(0, rh_chord)
    m_piano.insert(0, lh_stream)

    # Cello's lyrical melody
    if i == 0: add_notes_to_measure(m_cello, [('G3', 4.0)])
    if i == 1: add_notes_to_measure(m_cello, [('C4', 3.0), ('Bb3', 1.0)])
    if i == 2: add_notes_to_measure(m_cello, [('Ab3', 2.0), ('G3', 2.0)])
    if i == 3: add_notes_to_measure(m_cello, [('F3', 3.0), ('G3', 1.0)])
    if i == 4: add_notes_to_measure(m_cello, [('Ab3', 1.5), ('Bb3', 0.5), ('C4', 2.0)])
    if i == 5: add_notes_to_measure(m_cello, [('Db4', 3.0), ('C4', 1.0)])
    if i == 6: add_notes_to_measure(m_cello, [('Bb3', 2.0), ('Eb4', 2.0)])
    if i == 7: add_notes_to_measure(m_cello, [('D4', 4.0)])

    piano_part.append(m_piano)
    cello_part.append(m_cello)

# Measures 17-24: Development - Interaction and tension
for i in range(8):
    m_piano = stream.Measure(number=17+i)
    m_cello = stream.Measure(number=17+i)

    # Piano becomes more melodic and agitated
    if i == 0: add_notes_to_measure(m_piano, [(['G2', 'D3', 'F3'], 1.0), (['G2', 'D3', 'F3'], 1.0), (['G2', 'D3', 'F3'], 2.0)])
    if i == 1: add_notes_to_measure(m_piano, [(['C3', 'E3', 'G3'], 1.0), (['C3', 'E3', 'G3'], 1.0), (['C3', 'E3', 'G3'], 2.0)])
    if i == 2: add_notes_to_measure(m_piano, [(['F#2', 'A2', 'E3'], 2.0), (['A2', 'C#3', 'G3'], 2.0)])
    if i == 3: add_notes_to_measure(m_piano, [(['B2', 'D3', 'A3'], 4.0)])
    if i == 4: add_notes_to_measure(m_piano, [(['E2', 'B2', 'G3'], 1.0), ('G3', 0.5), ('F#3', 0.5), ('E3', 0.5), ('D3', 0.5), ('C#3', 1.0)])
    if i == 5: add_notes_to_measure(m_piano, [(['A1', 'E2', 'C3'], 4.0)])
    if i == 6: add_notes_to_measure(m_piano, [('D2', 1), ('F#2', 1), ('A2', 1), ('C3', 1)])
    if i == 7: add_notes_to_measure(m_piano, [(['G2', 'B2', 'F3'], 4.0)])

    # Cello is more rhythmic and intense
    if i == 0: add_notes_to_measure(m_cello, [('Eb4', 1.5), ('D4', 0.5), ('Eb4', 2.0)])
    if i == 1: add_notes_to_measure(m_cello, [('G4', 1.5), ('F4', 0.5), ('E4', 2.0)])
    if i == 2: add_notes_to_measure(m_cello, [('A4', 2.0), ('G4', 2.0)])
    if i == 3: add_notes_to_measure(m_cello, [('F#4', 4.0)])
    if i == 4: add_notes_to_measure(m_cello, [('E4', 1.0), ('F#4', 1.0), ('G4', 1.0), ('A4', 1.0)])
    if i == 5: add_notes_to_measure(m_cello, [('G4', 4.0)])
    if i == 6: add_notes_to_measure(m_cello, [('F#4', 2.0), ('E4', 1.0), ('D4', 1.0)])
    if i == 7: add_notes_to_measure(m_cello, [('C4', 4.0)])

    piano_part.append(m_piano)
    cello_part.append(m_cello)

# Measures 25-32: Recapitulation & Coda
for i in range(8):
    m_piano = stream.Measure(number=25+i)
    m_cello = stream.Measure(number=25+i)

    # Return of ostinato, but softer and higher
    if i < 4:
        rh = chord.Chord(['G5', 'Bb5', 'Eb6'], quarterLength=4.0)
        rh.volume.velocity = 40 # pianissimo
        lh_notes = [('C3', 1), ('G3', 1), ('C4', 1), ('G3', 1)]
        lh_stream = stream.Stream()
        for n, d in lh_notes:
            note_obj=note.Note(n, quarterLength=d)
            note_obj.volume.velocity=40
            lh_stream.append(note_obj)
        m_piano.insert(0, rh)
        m_piano.insert(0, lh_stream)

    # Cello holds a high note, then descends
    if i == 0: m_cello.append(note.Note('G4', quarterLength=4.0))
    if i == 1: m_cello.notesAndRests[0].tie = tie.Tie('start')
    if i == 1: m_cello.append(note.Note('G4', quarterLength=4.0))
    if i == 2: add_notes_to_measure(m_cello, [('F4', 2.0), ('Eb4', 2.0)])
    if i == 3: add_notes_to_measure(m_cello, [('D4', 2.0), ('C4', 2.0)])

    #Coda - Fading out
    if i == 4: 
        add_notes_to_measure(m_piano, [(['C3', 'G3', 'C4', 'Eb4'], 4.0)])
        m_piano.notes[0].lyric = 'rit.'
        add_notes_to_measure(m_cello, [('G3', 4.0)])
    if i == 5: 
        add_notes_to_measure(m_piano, [(['C2', 'G2', 'C3'], 4.0)])
        add_notes_to_measure(m_cello, [('C3', 4.0)])
    if i == 6:
        final_chord = chord.Chord(['C2', 'C3'], quarterLength=4)
        final_chord.articulations.append(articulations.Fermata())
        m_piano.append(final_chord)
        final_note = note.Note('C2', quarterLength=4)
        final_note.articulations.append(articulations.Fermata())
        m_cello.append(final_note)
    if i == 7:
        m_piano.append(note.Rest(quarterLength=4))
        m_cello.append(note.Rest(quarterLength=4))

    piano_part.append(m_piano)
    cello_part.append(m_cello)

# 3. Final Assembly
score.insert(0, piano_part)
score.insert(0, cello_part)
